189	        String idempotencyKey = idempotencyKey();
190	        if (idempotencyKey != null) {
191	            Integer existingId = idempotentOwnerIds.get(idempotencyKey);
192	            if (existingId != null) {
193	                Owner existing = this.clinicService.findOwnerById(existingId);
194	                if (existing != null) {
195	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
196	                }
197	            }
198	        }
199	        validateRequiredOwnerFields(ownerFieldsDto);
200	        HttpHeaders headers = new HttpHeaders();
201	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
202	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
203	        owner.setTelephone(normalizedTelephone);
204	        owner.setEmail(normalizeEmail(owner.getEmail()));
205	        applyAddress(owner);
206	        validatePostcode(owner.getPostcode(), owner.getCity());
207	        rejectFutureRegistrationDate(owner.getRegistrationDate());
208	        LocalDate effectiveRegistrationDate =
209	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
210	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
211	        rejectDailyLimitReached(owner.getRegistrationDate());
212	        rejectCityAtCapacity(owner.getCity());
213	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
214	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
215	        rejectDuplicateIdentity(owner, sharesHousehold);
216	        assignPossibleDuplicate(owner, sharesHousehold);
217	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
218	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
219	        owner.setHouseholdSize(countHousehold(owner.getHouseholdId()));
220	        owner.setMembershipLevelCap(membershipLevelCap(owner.getHouseholdId()));
221	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
222	        this.clinicService.saveOwner(owner);
223	        if (idempotencyKey != null) {
224	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
225	        }
226	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
227	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
228	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
229	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
230	        headers.setLocation(UriComponentsBuilder.newInstance()
231	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
232	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
233	    }
