235	    /**
236	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, returning
237	     * {@code null} when the header is absent or blank so callers can treat those uniformly as "no key".
238	     *
239	     * @return the trimmed idempotency key, or {@code null} when none was supplied
240	     */
241	    private String idempotencyKey() {
242	        String value = request.getHeader(IDEMPOTENCY_KEY_HEADER);
243	        if (value == null || value.isBlank()) {
244	            return null;
245	        }
246	        return value.strip();
247	    }
