298	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
299	    @Override
300	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
301	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
302	        if (currentOwner != null) {
303	            Pet currentPet = this.clinicService.findPetById(petId);
304	            if (currentPet != null) {
