363	    /**
364	     * Builds the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'} where
365	     * {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion})
366	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
367	     * normalized telephone concatenated with the last name. For example an owner in the NSW postcode
368	     * range gets a code such as {@code 'NSW-3F2A1B9C'}.
369	     *
370	     * <p>When the computed code collides with an existing owner's customer code, it is de-duplicated
371	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result
372	     * unique across all existing owners' customer codes. The de-duplicated code is what gets assigned.
373	     *
374	     * @param owner the owner being created, whose postcode, city and last name feed the code
375	     * @param normalizedTelephone the owner's E.164-normalized telephone
376	     * @return the assigned customer code, de-duplicated against existing owners if necessary
377	     */
378	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
379	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
380	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
381	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
382	        String baseCode = region + "-" + hash8;
383	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
384	            .map(Owner::getCustomerCode)
385	            .filter(code -> code != null)
386	            .collect(java.util.stream.Collectors.toSet());
387	        if (!existingCodes.contains(baseCode)) {
388	            return baseCode;
389	        }
390	        int n = 2;
391	        while (existingCodes.contains(baseCode + "-" + n)) {
392	            n++;
393	        }
394	        return baseCode + "-" + n;
395	    }
