397	    /**
398	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
399	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
400	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
401	     *
402	     * @param postcode the owner's postcode, may be {@code null}
403	     * @param city the owner's city, used to resolve the region when the postcode does not
404	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
405	     */
406	    private String deriveRegion(String postcode, String city) {
407	        if (postcode != null) {
408	            try {
409	                int value = Integer.parseInt(postcode.trim());
410	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
411	                    int[] range = entry.getValue();
412	                    if (value >= range[0] && value <= range[1]) {
413	                        return entry.getKey();
414	                    }
415	                }
416	            } catch (NumberFormatException ex) {
417	                // Not a numeric postcode; fall back to the city table below.
418	            }
419	        }
420	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
421	    }
422	
423	    /**
424	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
425	     * given input's UTF-8 bytes.
426	     *
427	     * @param input the string to hash
428	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
429	     */
430	    private String sha256Hex8(String input) {
431	        try {
432	            byte[] digest = MessageDigest.getInstance("SHA-256")
433	                .digest(input.getBytes(StandardCharsets.UTF_8));
434	            StringBuilder hex = new StringBuilder();
435	            for (int i = 0; i < 4; i++) {
436	                hex.append(String.format("%02X", digest[i]));
437	            }
438	            return hex.toString();
439	        } catch (NoSuchAlgorithmException ex) {
440	            throw new IllegalStateException("SHA-256 not available", ex);
441	        }
442	    }
