494	    /**
495	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
496	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
497	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
498	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
499	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
500	     * and returned exactly as given.
501	     *
502	     * @param postcode the submitted postcode, may be {@code null} when absent
503	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
504	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
505	     */
506	    private void validatePostcode(String postcode, String city) {
507	        if (postcode == null) {
508	            return;
509	        }
510	        if (!postcode.matches("[0-9]{4}")) {
511	            throw new InvalidOwnerFieldsException(List.of("postcode"));
512	        }
513	        String region = city == null ? null : CITY_REGION.get(city);
514	        if (region == null) {
515	            return;
516	        }
517	        int[] range = REGION_POSTCODES.get(region);
518	        int value = Integer.parseInt(postcode);
519	        if (value < range[0] || value > range[1]) {
520	            throw new InvalidOwnerFieldsException(List.of("postcode"));
521	        }
522	    }
