524	    /**
525	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
526	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
527	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
528	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
529	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
530	     *
531	     * @param telephone the raw telephone value from the submitted owner payload
532	     * @return the normalized E.164 telephone number
533	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
534	     */
535	    private String normalizeTelephone(String telephone) {
536	        String raw = telephone == null ? "" : telephone.strip();
537	        boolean hasCountryCode = raw.startsWith("+");
538	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
539	        String digits;
540	        if (hasCountryCode) {
541	            digits = cleaned.substring(1);
542	        } else {
543	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
544	            digits = "61" + national;
545	        }
546	        if (!digits.matches("[0-9]{8,15}")) {
547	            throw new InvalidOwnerFieldsException(List.of("telephone"));
548	        }
549	        validateNationalNumberLength(digits);
550	        return "+" + digits;
551	    }
552	
553	    /**
554	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
555	     * country calling code) has the exact length required for that country. The country code is matched
556	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
557	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
558	     *
559	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
560	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
561	     */
562	    private void validateNationalNumberLength(String digits) {
563	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
564	            String countryCode = entry.getKey();
565	            if (digits.startsWith(countryCode)) {
566	                int nationalLength = digits.length() - countryCode.length();
567	                if (nationalLength != entry.getValue()) {
568	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
569	                }
570	                return;
571	            }
572	        }
573	    }
