575	    /**
576	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
577	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
578	     * accepted value is trimmed and lower-cased before it is stored and returned.
579	     *
580	     * @param email the raw email value from the submitted owner payload, may be {@code null}
581	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
582	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
583	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
584	     */
585	    private String normalizeEmail(String email) {
586	        if (email == null) {
587	            return null;
588	        }
589	        String trimmed = email.strip();
590	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
591	            throw new InvalidOwnerFieldsException(List.of("email"));
592	        }
593	        String normalized = trimmed.toLowerCase(Locale.ROOT);
594	        String domain = normalized.substring(normalized.indexOf('@') + 1);
595	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
596	            throw new InvalidOwnerFieldsException(List.of("email"));
597	        }
598	        return normalized;
599	    }
