601	    /**
602	     * Rejects creating an owner whose derived identity key (the SHA-256 hex digest of
603	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}, see {@link OwnerMapper#identityKey})
604	     * exactly equals that of an existing non-deleted owner. Two owners are treated as duplicates only when
605	     * their whole identity keys match, so owners who share a last-name Soundex but differ in telephone or
606	     * email are not duplicates and are admitted (flagged as a soft match instead). Such an owner is rejected
607	     * with a 409, <em>unless</em> the request opts into {@code sharesHousehold}, which bypasses the block
608	     * entirely.
609	     *
610	     * @param owner the owner being created, whose identity key is matched
611	     * @param sharesHousehold whether the request declared the owner a shared-household member
612	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key
613	     */
614	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
615	        if (sharesHousehold) {
616	            return;
617	        }
618	        String identityKey = ownerMapper.identityKey(owner);
619	        boolean duplicate = this.clinicService.findAllOwners().stream()
620	            .filter(existing -> !isDeleted(existing))
621	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
622	        if (duplicate) {
623	            throw new DuplicateOwnerIdentityException(identityKey);
624	        }
625	    }
626	
627	    /**
628	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
629	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
630	     * owner whose {@link OwnerMapper#identityKey identity key} <em>differs</em> from an existing owner's
631	     * but which shares that owner's last-name {@link OwnerMapper#soundex Soundex code} and postcode. When
632	     * such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
633	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
634	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
635	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
636	     *
637	     * <p>Because the telephone is part of the identity key, two owners with the same last name and postcode
638	     * but different telephones no longer collide on the identity key, so they are admitted as a soft match
639	     * here rather than rejected as a hard household duplicate.
640	     *
641	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the duplicate
642	     * block) is never a <em>suspected</em> duplicate: it is knowingly created as another member of the
643	     * household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
644	     * {@code null} without consulting the existing population.
645	     *
646	     * @param owner the owner being created, whose last-name Soundex and postcode are matched
647	     * @param sharesHousehold whether the request declared the owner a shared-household member
648	     */
649	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
650	        if (sharesHousehold) {
651	            owner.setPossibleDuplicateOf(null);
652	            owner.setPossibleDuplicate(false);
653	            return;
654	        }
655	        String postcode = owner.getPostcode();
656	        Integer matchId = null;
657	        if (postcode != null) {
658	            String identityKey = ownerMapper.identityKey(owner);
659	            String lastNameCode = OwnerIdentity.soundex(owner.getLastName());
660	            for (Owner existing : this.clinicService.findAllOwners()) {
661	                if (!isDeleted(existing)
662	                    && postcode.equals(existing.getPostcode())
663	                    && lastNameCode.equals(OwnerIdentity.soundex(existing.getLastName()))
664	                    && !identityKey.equals(ownerMapper.identityKey(existing))
665	                    && existing.getId() != null
666	                    && (matchId == null || existing.getId() < matchId)) {
667	                    matchId = existing.getId();
668	                }
669	            }
670	        }
671	        owner.setPossibleDuplicateOf(matchId);
672	        owner.setPossibleDuplicate(matchId != null);
673	    }
