675	    /**
676	     * The maximum number of owners a single city may contain. Once a city already holds this many
677	     * owners, creating another owner in that city is rejected.
678	     */
679	    private static final int MAX_OWNERS_PER_CITY = 50;
680	
681	    /**
682	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
683	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
684	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
685	     * counting used elsewhere.
686	     *
687	     * @param city the city of the owner being created
688	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
689	     */
690	    /**
691	     * The maximum number of owners that may be registered on a single day. Once this many owners
692	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
693	     */
694	    private static final int MAX_OWNERS_PER_DAY = 100;
