707	    /**
708	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
709	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
710	     * registration date of the owner being created.
711	     *
712	     * @param registrationDate the registration date of the owner being created
713	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
714	     */
715	    /**
716	     * Rolls an effective registration date forward onto a business day. A registration date must fall
717	     * on a weekday that is not a public holiday: when the supplied or defaulted date is a Saturday, a
718	     * Sunday, or a listed public holiday it is rolled forward one day at a time until it reaches the
719	     * next non-holiday business day, and that adjusted date becomes the owner's {@code registrationDate}.
720	     * A date that is already a non-holiday weekday is returned unchanged. Every value derived from the
721	     * registration date (the daily create-limit count, the membership number's year segment, and so on)
722	     * uses this adjusted date.
723	     *
724	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
725	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
726	     */
727	    /**
728	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
729	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
730	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
731	     * against the date exactly as supplied, before it is rolled forward onto a business day.
732	     *
733	     * @param registrationDate the registration date supplied in the request, may be {@code null}
734	     * @throws FutureRegistrationDateException if the supplied date is after the server date
735	     */
736	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
737	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
738	            throw new FutureRegistrationDateException(registrationDate);
739	        }
740	    }
741	
742	    private LocalDate rollToBusinessDay(LocalDate date) {
743	        LocalDate adjusted = date;
744	        while (!isBusinessDay(adjusted)) {
745	            adjusted = adjusted.plusDays(1);
746	        }
747	        return adjusted;
748	    }
