750	    private boolean isBusinessDay(LocalDate date) {
751	        DayOfWeek day = date.getDayOfWeek();
752	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
753	            return false;
754	        }
755	        return !PUBLIC_HOLIDAYS.contains(date);
756	    }
