759	        long ownersToday = this.clinicService.findAllOwners().stream()
760	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
761	            .count();
762	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
763	            throw new DailyOwnerLimitExceededException(registrationDate);
764	        }
