820	
821	    /**
822	     * Computes the membership-level ceiling for the owner being created, snapshotted at creation time.
823	     * A new owner's membership level cannot exceed one above the current maximum membership level among
824	     * their existing household members: the returned cap is that maximum plus one. Existing household
825	     * members are the non-deleted owners already carrying the same {@code householdId}, and their
826	     * membership level is their effective (already-capped) {@link OwnerMapper#membershipLevel level}.
827	     * Returns {@code null} when there is no existing household member, in which case no cap applies.
828	     *
829	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
830	     * @return one above the highest household member's membership level, or {@code null} when none exist
831	     */
832	    private Integer membershipLevelCap(String householdId) {
833	        if (householdId == null) {
834	            return null;
835	        }
836	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
837	            .filter(existing -> !isDeleted(existing))
838	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
839	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
840	            .max();
841	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
842	    }
843	
844	    /**
845	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
846	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
847	     * name is normalized for case- and whitespace-insensitive comparison (see
848	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
849	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
850	     * regardless of creation order, making them members of one household.
851	     *
852	     * @param lastName the owner's last name
853	     * @param postcode the owner's postcode, may be {@code null}
854	     * @return the deterministic household identifier
855	     */
856	    private String householdId(String lastName, String postcode) {
857	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
858	        try {
859	            byte[] digest = MessageDigest.getInstance("SHA-256")
860	                .digest(key.getBytes(StandardCharsets.UTF_8));
861	            StringBuilder hex = new StringBuilder();
862	            for (int i = 0; i < 6; i++) {
863	                hex.append(String.format("%02x", digest[i]));
864	            }
865	            return hex.toString();
866	        } catch (NoSuchAlgorithmException ex) {
867	            throw new IllegalStateException("SHA-256 not available", ex);
868	        }
869	    }
870	
871	    /**
872	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
873	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
874	     * result is lower-cased. A {@code null} value normalizes to the empty string.
875	     *
876	     * @param value the value to normalize, may be {@code null}
877	     * @return the normalized value
878	     */
879	    private String normalizeForComparison(String value) {
880	        if (value == null) {
881	            return "";
882	        }
883	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
884	    }
885	
886	    /**
887	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
888	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
889	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
890	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
891	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
892	     * that is stored, returned, and used for every address comparison (household duplicate detection
893	     * and the shared household id).
894	     *
895	     * @param address the raw address value from the submitted owner payload, may be {@code null}
896	     * @return the normalized address
897	     */
898	    /**
899	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
900	     * the structured fields over the flat {@code address} input for backward compatibility. When a
901	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
902	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
903	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
904	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
905	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
906	     *
907	     * @param owner the owner being created, whose raw address fields are normalized in place
908	     */
909	    private void applyAddress(Owner owner) {
910	        String line1 = owner.getAddressLine1();
911	        if (line1 != null && !line1.isBlank()) {
912	            String normalizedLine1 = normalizeAddress(line1);
913	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
914	            owner.setAddressLine1(normalizedLine1);
915	            if (!normalizedLine2.isEmpty()) {
916	                owner.setAddressLine2(normalizedLine2);
917	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
918	            } else {
919	                owner.setAddressLine2(null);
920	                owner.setAddress(normalizedLine1);
921	            }
922	        } else {
923	            owner.setAddressLine1(null);
924	            owner.setAddressLine2(null);
925	            owner.setAddress(normalizeAddress(owner.getAddress()));
926	        }
927	    }
928	
929	    private String normalizeAddress(String address) {
930	        if (address == null) {
931	            return "";
932	        }
933	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
934	        if (collapsed.isEmpty()) {
935	            return "";
936	        }
937	        String[] tokens = collapsed.split(" ");
938	        StringBuilder normalized = new StringBuilder();
939	        for (int i = 0; i < tokens.length; i++) {
940	            if (i > 0) {
941	                normalized.append(' ');
942	            }
943	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
944	        }
945	        return normalized.toString();
946	    }
947	}
